import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingApprove } from '../@mappers/hikingApprove.mapper';
import {
  HikingApproveEntityType,
  IHikingApproveDTO,
  IHikingApproveSetDTO,
  IHikingApproveSetResultDTO,
  IHikingApprovesListCriteria,
  IHikingApproveUnsetDTO,
} from '../@types/DTO/hikingApprovers.dto.types';

export const getHikingApprovesForEntityType = async (
  id_hiking: number,
  entity_type: HikingApproveEntityType,
  entity_id: number | null,
) => {
  const res = await get<IHikingApproveDTO[], IHikingApprovesListCriteria>(
    '/ajax/hiking/approvers/get_approvers.php',
    { id_hiking, entity_type, entity_id },
  ).then(handleApiError);
  return res.map(mapHikingApprove);
};

export const approveHikingEntity = async (data: IHikingApproveSetDTO) => {
  const res = await post<IHikingApproveSetResultDTO, IHikingApproveSetDTO>(
    '/ajax/hiking/approvers/approve.php',
    data,
  ).then<IHikingApproveSetResultDTO>(handleApiError);
  return +res.id;
};

export const disapproveHikingEntity = async (data: IHikingApproveUnsetDTO) => {
  const res = await post<{ success: boolean }, IHikingApproveUnsetDTO>(
    '/ajax/hiking/approvers/disapprove.php',
    data,
  ).then<{ success: boolean }>(handleApiError);
  return !!res.success;
};
