import React from 'react';

import PatchCheckFill from '@pohodnik/icons/svg/Badges/PatchCheckFill';
import Award from '@pohodnik/icons/svg/RealWorld/Award';
import AwardFill from '@pohodnik/icons/svg/RealWorld/AwardFill';

import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { AuthContext } from '../../../contexts/AuthContext';
import {
  approveHikingEntity,
  disapproveHikingEntity,
  getHikingApprovesForEntityType,
} from '../@services/hikingApprove.service';
import { HikingApproveEntityType } from '../@types/DTO/hikingApprovers.dto.types';
import { HikingPosition } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingApprove } from '../@types/hikingApprovers.types';

const entityTypePositions: Record<HikingApproveEntityType, HikingPosition[]> = {
  ['obstacle']: [HikingPosition.Rukovidotel, HikingPosition.Shturman],
  ['schedule']: [HikingPosition.Rukovidotel, HikingPosition.Shturman, HikingPosition.Logist],
  ['menu']: [HikingPosition.Rukovidotel, HikingPosition.Zavkhoz],
  ['first_aid_kit']: [HikingPosition.Rukovidotel, HikingPosition.Medic],
  ['repair_kit']: [HikingPosition.Rukovidotel, HikingPosition.Remmaster],
};

interface IHikingApprovesProps {
  entity_type: HikingApproveEntityType;
  entity_id?: number;
  hikingData: IHikingData;
  readonly?: boolean;
  onApprovesStateChanged?: (approves: IHikingApprove[]) => void;
}

const HikingApproves: React.FC<IHikingApprovesProps> = ({
  hikingData,
  entity_type,
  entity_id = null,
  onApprovesStateChanged,
  readonly = false,
}) => {
  const [approves, setApproves] = React.useState<IHikingApprove[]>([]);
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    if (!authContext.user?.id) return;
    getHikingApprovesForEntityType(hikingData.id, entity_type, entity_id).then((a) => {
      setApproves(a);
      onApprovesStateChanged?.(a);
    });
  }, [hikingData.id]);

  if (!authContext.user?.id) return null;

  return (
    <div>
      {hikingData.hikers.map((hiker) => {
        const relevantPositions = hiker.positions.filter((p) =>
          entityTypePositions[entity_type]?.includes(p.id as HikingPosition),
        );
        if (!relevantPositions.length) return null;

        return (
          <div key={hiker.idUser}>
            {relevantPositions.map((pos) => {
              const approveData = approves.find(
                (a) => a.user.id === hiker.idUser && a.position.id === pos.id,
              );

              if (readonly && !approveData) return null;

              return (
                <PohRow className="align-items-center" key={hiker.idUser + '_' + pos.id}>
                  <PohCol xs={3}>
                    {approveData ? <AwardFill className="text-success" /> : <Award />}
                    {pos.name}
                  </PohCol>
                  <PohCol xs={3}>
                    <em>{[hiker.name, hiker.surname].join(' ')}</em>
                  </PohCol>
                  <PohCol xs={3}>
                    {approveData ? (
                      <strong className="text-success">
                        <small>{approveData.created_at.toLocaleString()}</small> <PatchCheckFill />
                      </strong>
                    ) : (
                      <small className="text-muted">Ожидает утверждения</small>
                    )}
                  </PohCol>
                  <PohCol xs={3}>
                    {!readonly && authContext.user?.id && +authContext.user.id === hiker.idUser && (
                      <span className="ms-auto">
                        <PohButton
                          size={ButtonSize.Small}
                          variant={approveData ? ButtonVariant.Light : ButtonVariant.Success}
                          onClick={async (e) => {
                            const btn = e.target as HTMLButtonElement;
                            btn.disabled = true;
                            if (approveData) {
                              await disapproveHikingEntity({ id: approveData.id });
                              setApproves((cur) => cur.filter((c) => c.id !== approveData.id));
                              notificationHelper.success('Отменено!');
                            } else {
                              const newId = await approveHikingEntity({
                                entity_id,
                                entity_type,
                                id_position: pos.id,
                                id_hiking: hikingData.id,
                              });
                              setApproves((cur) => [
                                ...cur,
                                {
                                  id: newId,
                                  created_at: new Date(),
                                  entity_id,
                                  entity_type,
                                  position: pos,
                                  user: {
                                    id: hiker.idUser,
                                    name: hiker.name,
                                    surname: hiker.surname,
                                    photo: hiker.photo['50'],
                                  },
                                },
                              ]);
                              notificationHelper.success('Утверждено!');
                            }
                            btn.disabled = false;
                          }}
                        >
                          {approveData ? 'Отменить утверждение' : 'Утвердить'}
                        </PohButton>
                      </span>
                    )}
                  </PohCol>
                </PohRow>
              );
            })}
          </div>
        );
      })}
    </div>
  );
};

export default HikingApproves;
